{"file_path": "arkan-backend/src/server.ts", "initial_content": "/**
 * Arkan Backend Server
 * Main entry point for the Express REST API
 */

import express, { Application } from 'express';
import cors from 'cors';
import helmet from 'helmet';
import morgan from 'morgan';
import compression from 'compression';
import { config } from '@/config/environment';
import { errorHandler } from '@/middleware/error-handler';
import { requestLogger } from '@/middleware/request-logger';
import { rateLimiter } from '@/middleware/rate-limiter';
import logger from '@/utils/logger';

// Import routes
import authRoutes from '@/routes/auth.routes';
import userRoutes from '@/routes/user.routes';
import projectRoutes from '@/routes/project.routes';
import flowRoutes from '@/routes/flow.routes';
import agentRoutes from '@/routes/agent.routes';
import adminRoutes from '@/routes/admin.routes';
import ragRoutes from '@/routes/rag.routes';
import generationRoutes from '@/routes/generation.routes';
import templateRoutes from '@/routes/template.routes';
import writingToolsRoutes from '@/routes/writing-tools.routes';
import healthRoutes from '@/routes/health.routes';

class Server {
  private app: Application;
  private port: number;

  constructor() {
    this.app = express();
    this.port = config.port;
    this.initializeMiddlewares();
    this.initializeRoutes();
    this.initializeErrorHandling();
  }

  private initializeMiddlewares(): void {
    // Security
    this.app.use(helmet());

    // CORS
    this.app.use(cors({
      origin: config.corsOrigin.split(','),
      credentials: true,
      methods: ['GET', 'POST', 'PUT', 'DELETE', 'PATCH', 'OPTIONS'],
      allowedHeaders: ['Content-Type', 'Authorization', 'X-Requested-With']
    }));

    // Body parsing
    this.app.use(express.json({ limit: '10mb' }));
    this.app.use(express.urlencoded({ extended: true, limit: '10mb' }));

    // Compression
    this.app.use(compression());

    // Logging
    if (config.nodeEnv === 'development') {
      this.app.use(morgan('dev'));
    }
    this.app.use(requestLogger);

    // Rate limiting
    this.app.use(rateLimiter);
  }

  private initializeRoutes(): void {
    const apiPrefix = `/api/${config.apiVersion}`;

    // Health check
    this.app.use(`${apiPrefix}/health`, healthRoutes);

    // Public routes
    this.app.use(`${apiPrefix}/auth`, authRoutes);

    // Protected routes
    this.app.use(`${apiPrefix}/users`, userRoutes);
    this.app.use(`${apiPrefix}/projects`, projectRoutes);
    this.app.use(`${apiPrefix}/flows`, flowRoutes);
    this.app.use(`${apiPrefix}/agents`, agentRoutes);
    this.app.use(`${apiPrefix}/generation`, generationRoutes);
    this.app.use(`${apiPrefix}/templates`, templateRoutes);
    this.app.use(`${apiPrefix}/writing-tools`, writingToolsRoutes);
    this.app.use(`${apiPrefix}/rag`, ragRoutes);

    // Admin routes
    this.app.use(`${apiPrefix}/admin`, adminRoutes);

    // 404 handler
    this.app.use('*', (req, res) => {
      res.status(404).json({
        success: false,
        message: 'Route not found'
      });
    });
  }

  private initializeErrorHandling(): void {
    this.app.use(errorHandler);
  }

  public start(): void {
    this.app.listen(this.port, () => {
      logger.info(`🚀 Arkan Backend Server running on port ${this.port}`);
      logger.info(`📡 API available at http://localhost:${this.port}/api/${config.apiVersion}`);
      logger.info(`🌍 Environment: ${config.nodeEnv}`);
    });
  }
}

// Start server
const server = new Server();
server.start();

export default server;
"}

