{"file_path": "arkan-backend/src/controllers/flow.controller.ts", "initial_content": "/**
 * Flow Controller
 * Handles flow execution requests
 */

import { Request, Response, NextFunction } from 'express';
import { AuthRequest } from '@/middleware/auth';
import { dynamicFlowExecutor } from '@/ai/flows/dynamic-flow-executor';
import { AppError } from '@/middleware/error-handler';

export const executeFlow = async (
  req: AuthRequest,
  res: Response,
  next: NextFunction
) => {
  try {
    const { flowName, payload, enableTracing } = req.body;

    if (!flowName) {
      throw new AppError('Flow name is required', 400);
    }

    if (!payload || typeof payload !== 'object') {
      throw new AppError('Payload object is required', 400);
    }

    const result = await dynamicFlowExecutor({
      flowName,
      payload,
      userId: req.user!.uid,
      requestId: `req_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`,
      enableTracing: enableTracing ?? true,
    });

    res.json(result);
  } catch (error) {
    next(error);
  }
};

export const testFlow = async (
  req: AuthRequest,
  res: Response,
  next: NextFunction
) => {
  try {
    const { flowConfig, payload } = req.body;

    if (!flowConfig) {
      throw new AppError('Flow configuration is required', 400);
    }

    // Test flow logic here
    res.json({
      success: true,
      message: 'Flow test completed',
    });
  } catch (error) {
    next(error);
  }
};
"}

{"file_path": "arkan-backend/src/controllers/auth.controller.ts", "initial_content": "/**
 * Auth Controller
 */

import { Request, Response, NextFunction } from 'express';
import { AuthRequest } from '@/middleware/auth';
import { adminAuth, adminDb } from '@/config/firebase-admin';
import { AppError } from '@/middleware/error-handler';

export const signup = async (
  req: Request,
  res: Response,
  next: NextFunction
) => {
  try {
    const { email, password, displayName } = req.body;

    if (!email || !password) {
      throw new AppError('Email and password are required', 400);
    }

    const userRecord = await adminAuth.createUser({
      email,
      password,
      displayName,
    });

    // Create user document in Firestore
    await adminDb.collection('users').doc(userRecord.uid).set({
      email,
      displayName,
      credits: 100, // Starting credits
      role: 'user',
      createdAt: new Date().toISOString(),
    });

    res.status(201).json({
      success: true,
      user: {
        uid: userRecord.uid,
        email: userRecord.email,
        displayName: userRecord.displayName,
      },
    });
  } catch (error) {
    next(error);
  }
};

export const login = async (
  req: Request,
  res: Response,
  next: NextFunction
) => {
  try {
    // Client handles Firebase Auth login
    // This endpoint can be used for additional server-side logic
    res.json({
      success: true,
      message: 'Login handled by client Firebase SDK',
    });
  } catch (error) {
    next(error);
  }
};

export const logout = async (
  req: AuthRequest,
  res: Response,
  next: NextFunction
) => {
  try {
    // Revoke refresh tokens
    if (req.user) {
      await adminAuth.revokeRefreshTokens(req.user.uid);
    }

    res.json({
      success: true,
      message: 'Logged out successfully',
    });
  } catch (error) {
    next(error);
  }
};

export const getSession = async (
  req: AuthRequest,
  res: Response,
  next: NextFunction
) => {
  try {
    res.json({
      success: true,
      user: req.user,
    });
  } catch (error) {
    next(error);
  }
};
"}

{"file_path": "arkan-backend/src/controllers/project.controller.ts", "initial_content": "/**
 * Project Controller
 */

import { Response, NextFunction } from 'express';
import { AuthRequest } from '@/middleware/auth';
import { adminDb } from '@/config/firebase-admin';
import { AppError } from '@/middleware/error-handler';

export const getAllProjects = async (
  req: AuthRequest,
  res: Response,
  next: NextFunction
) => {
  try {
    const snapshot = await adminDb
      .collection('projects')
      .where('userId', '==', req.user!.uid)
      .orderBy('createdAt', 'desc')
      .get();

    const projects = snapshot.docs.map(doc => ({
      id: doc.id,
      ...doc.data(),
    }));

    res.json({
      success: true,
      projects,
    });
  } catch (error) {
    next(error);
  }
};

export const createProject = async (
  req: AuthRequest,
  res: Response,
  next: NextFunction
) => {
  try {
    const projectData = {
      ...req.body,
      userId: req.user!.uid,
      createdAt: new Date().toISOString(),
      updatedAt: new Date().toISOString(),
    };

    const docRef = await adminDb.collection('projects').add(projectData);

    res.status(201).json({
      success: true,
      project: {
        id: docRef.id,
        ...projectData,
      },
    });
  } catch (error) {
    next(error);
  }
};

export const getProject = async (
  req: AuthRequest,
  res: Response,
  next: NextFunction
) => {
  try {
    const { id } = req.params;
    const doc = await adminDb.collection('projects').doc(id).get();

    if (!doc.exists) {
      throw new AppError('Project not found', 404);
    }

    const project = doc.data();
    if (project?.userId !== req.user!.uid) {
      throw new AppError('Unauthorized', 403);
    }

    res.json({
      success: true,
      project: {
        id: doc.id,
        ...project,
      },
    });
  } catch (error) {
    next(error);
  }
};

export const updateProject = async (
  req: AuthRequest,
  res: Response,
  next: NextFunction
) => {
  try {
    const { id } = req.params;
    const doc = await adminDb.collection('projects').doc(id).get();

    if (!doc.exists) {
      throw new AppError('Project not found', 404);
    }

    const project = doc.data();
    if (project?.userId !== req.user!.uid) {
      throw new AppError('Unauthorized', 403);
    }

    const updateData = {
      ...req.body,
      updatedAt: new Date().toISOString(),
    };

    await adminDb.collection('projects').doc(id).update(updateData);

    res.json({
      success: true,
      project: {
        id,
        ...project,
        ...updateData,
      },
    });
  } catch (error) {
    next(error);
  }
};

export const deleteProject = async (
  req: AuthRequest,
  res: Response,
  next: NextFunction
) => {
  try {
    const { id } = req.params;
    const doc = await adminDb.collection('projects').doc(id).get();

    if (!doc.exists) {
      throw new AppError('Project not found', 404);
    }

    const project = doc.data();
    if (project?.userId !== req.user!.uid) {
      throw new AppError('Unauthorized', 403);
    }

    await adminDb.collection('projects').doc(id).delete();

    res.json({
      success: true,
      message: 'Project deleted successfully',
    });
  } catch (error) {
    next(error);
  }
};
"}

